arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_4d171a04126a48d2846494da31565d66.Components.Apply
@using sv_4d171a04126a48d2846494da31565d66.Models
@using sv_4d171a04126a48d2846494da31565d66.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h3 class="mb-4">Job Application</h3>

    <StepIndicator CurrentStep="_currentStep"
                   StepNames="_stepNames"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="_personal"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="NextStep" />
